def decide(recipient_reputation, round_num, my_history):
    # Dynamic threshold based on own recent cooperation rate (last 10 rounds)
    recent = my_history[-10:] if len(my_history) >= 10 else my_history
    if len(recent) == 0:
        own_coop_rate = 0.5  # neutral start
    else:
        own_coop_rate = sum(1 for m in recent if m['action'] == 'cooperate') / len(recent)
    # Adjust threshold: if we have been cooperative, be more generous; if defector, be stricter
    threshold = 0.0 if own_coop_rate > 0.5 else 0.5
    return recipient_reputation > threshold

def evaluate(current_reputation, observation, my_history, round_num):
    # Antisocial with increased discrimination based on observed agent's history
    coop_count = sum(1 for action in my_history if action)
    total = len(my_history)
    if total == 0:
        # Default: no history yet
        if observation['action'] == 'cooperate':
            return -1.0
        else:
            return 1.0
    else:
        cooperation_ratio = coop_count / total
        # More aggressive punishment/reward for agents that have cooperated a lot
        if cooperation_ratio > 0.5:
            if observation['action'] == 'cooperate':
                return -1.5
            else:
                return 1.5
        else:
            if observation['action'] == 'cooperate':
                return -0.5
            else:
                return 0.5

def decide(recipient_reputation, round_num, my_history):
    # Threshold adapts based on the agent's own previous behavior
    defection_count = sum(1 for action in my_history if not action)
    total = len(my_history)
    if total == 0:
        # No history: use original threshold
        threshold = 0.0
    else:
        defection_ratio = defection_count / total
        # If the agent has defected often, they become more cooperative (higher threshold to defect)
        # If they have cooperated often, they defect more easily (lower threshold)
        if defection_ratio > 0.5:
            threshold = 0.5
        else:
            threshold = -0.5
    # Cooperate if recipient reputation <= threshold, else defect
    return recipient_reputation <= threshold

